#include "event_stream/mcp/query.h"
#include "event_stream/testing/build_event_stream.h"

#include <cstddef>
#include <filesystem>
#include <fmt/format.h>
#include <map>
#include <stdexcept>
#include <string>

#include <gtest/gtest.h>

namespace mcp = perf_streams::event_stream::mcp;
namespace event_testing = perf_streams::event_stream::testing;
namespace fs = std::filesystem;

class EventStreamMCPTest : public ::testing::Test
{
protected:
    static constexpr size_t default_memory_budget_bytes = 256 * 1024 * 1024;

    void SetUp() override
    {
        mcp::set_memory_budget(default_memory_budget_bytes);
        mcp::clear_cache();
    }

    void TearDown() override
    {
        mcp::clear_cache();
        mcp::set_memory_budget(default_memory_budget_bytes);
    }

    static std::string stream(const std::string& name)
    {
        return (fs::path(TEST_DIRECTORY) / "streams" / name).string();
    }

    static std::string stream_output(const std::string& name)
    {
        return (fs::path(TEST_OUTPUT_DIRECTORY) / name).string();
    }

    static std::string build_es(const std::string& name)
    {
        auto output_name = name.substr(0, name.rfind('.')) + ".es";
        return event_testing::build_es(stream(name), stream_output(output_name));
    }

    static std::map<std::string, uint64_t> metrics(const std::vector<mcp::Metric>& values)
    {
        std::map<std::string, uint64_t> result;
        for (const auto& metric : values)
            result[metric.name] = metric.value.as_uint();
        return result;
    }
};

TEST_F(EventStreamMCPTest, InspectExtractsMetadata)
{
    auto path = build_es("basic.in");
    auto result = mcp::inspect(path);

    EXPECT_EQ(result.stream_version, 4);
    EXPECT_EQ(result.event_count, 4);
    EXPECT_EQ(result.first_time, 100);
    EXPECT_EQ(result.last_time, 300);
    EXPECT_EQ(result.counts_by_definition["one"], 2);
    EXPECT_EQ(result.counts_by_definition["two"], 2);
    EXPECT_EQ(result.parameters.size(), 3);
}

TEST_F(EventStreamMCPTest, InspectFiltersMetadata)
{
    auto path = build_es("basic.in");

    mcp::InspectOptions name_options;
    name_options.name_filter = "DATA";
    auto name_result = mcp::inspect(path, name_options);
    ASSERT_EQ(name_result.definitions.size(), 2);
    EXPECT_EQ(name_result.definitions[0].name, "data1");
    EXPECT_EQ(name_result.definitions[1].name, "data2");
    EXPECT_TRUE(name_result.counts_by_definition.empty());
    EXPECT_TRUE(name_result.parameters.empty());

    mcp::InspectOptions description_options;
    description_options.description_filter = "VEN";
    auto description_result = mcp::inspect(path, description_options);
    ASSERT_EQ(description_result.definitions.size(), 2);
    EXPECT_EQ(description_result.definitions[0].name, "one");
    EXPECT_EQ(description_result.definitions[1].name, "two");
    EXPECT_EQ(description_result.counts_by_definition["one"], 2);
    EXPECT_EQ(description_result.counts_by_definition["two"], 2);

    mcp::InspectOptions param_options;
    param_options.name_filter = "MACHINE";
    auto param_result = mcp::inspect(path, param_options);
    ASSERT_EQ(param_result.parameters.size(), 1);
    EXPECT_EQ(param_result.parameters.front().name, "core.machine_width");
}

TEST_F(EventStreamMCPTest, CountParamsAndSample)
{
    auto path = build_es("basic.in");

    mcp::CountOptions count_options;
    auto count_result = mcp::count(path, count_options);
    auto count_metrics = metrics(count_result.summary);
    EXPECT_EQ(count_metrics["one"], 2);
    EXPECT_EQ(count_metrics["two"], 2);

    count_options.events = {"one"};
    count_options.accumulate = {"one/data1"};
    auto accumulated = metrics(mcp::count(path, count_options).summary);
    EXPECT_EQ(accumulated["one"], 2);
    EXPECT_EQ(accumulated["one/data1"], 42);

    mcp::ParamsOptions params_options;
    params_options.all = true;
    EXPECT_EQ(mcp::params(path, params_options).parameters.size(), 3);

    mcp::SampleOptions sample_options;
    sample_options.events = {"two"};
    sample_options.limit = 1;
    auto sample = mcp::sample(path, sample_options);
    ASSERT_EQ(sample.events.size(), 1);
    EXPECT_EQ(sample.events.front().name, "two");
    EXPECT_TRUE(sample.truncated);
}

TEST_F(EventStreamMCPTest, CountExpandsEnumerations)
{
    auto path = build_es("enums.in");
    mcp::CountOptions options;
    options.events = {"access/state"};
    auto result = metrics(mcp::count(path, options).summary);

    EXPECT_EQ(result["access"], 3);
    EXPECT_EQ(result["access/state:MISS"], 1);
    EXPECT_EQ(result["access/state:HIT"], 2);
}

TEST_F(EventStreamMCPTest, LatencyMatchesRepresentativeEVPBehavior)
{
    auto path = build_es("latency.in");
    mcp::LatencyOptions options;
    options.events = {"a", "b"};
    auto result = metrics(mcp::latency(path, options).summary);

    EXPECT_EQ(result["a_b.sum_latency"], 350);
    EXPECT_EQ(result["a_b.count"], 2);
    EXPECT_EQ(result["a_b.min_latency"], 100);
    EXPECT_EQ(result["a_b.max_latency"], 250);
}

TEST_F(EventStreamMCPTest, RateBuildsIntervalHistogram)
{
    auto path = build_es("basic.in");
    mcp::RateOptions options;
    options.interval = "one";
    options.events = {"two"};
    auto result = metrics(mcp::rate(path, options).summary);

    EXPECT_EQ(result["two.rate.1"], 2);
}

TEST_F(EventStreamMCPTest, CacheInvalidatesWhenFileIdentityChanges)
{
    auto output = stream_output("cache.es");
    auto path = event_testing::build_es(stream("basic.in"), output);
    EXPECT_EQ(mcp::inspect(path).event_count, 4);
    EXPECT_EQ(mcp::cache_stats().streams, 1);

    event_testing::build_es(stream("single.in"), output);
    EXPECT_EQ(mcp::inspect(path).event_count, 1);
}

TEST_F(EventStreamMCPTest, MemoryBudgetLimitsStreamLoading)
{
    auto path = build_es("basic.in");

    mcp::set_memory_budget(1);
    EXPECT_THROW({ static_cast<void>(mcp::inspect(path)); }, std::runtime_error);
    EXPECT_EQ(mcp::cache_stats().streams, 0);

    mcp::set_memory_budget(default_memory_budget_bytes);
    EXPECT_EQ(mcp::inspect(path).event_count, 4);
    EXPECT_GT(mcp::cache_stats().estimated_memory_bytes, 0);
}

TEST_F(EventStreamMCPTest, ReducingMemoryBudgetEvictsLoadedStreams)
{
    auto path = build_es("basic.in");

    EXPECT_EQ(mcp::inspect(path).event_count, 4);
    auto loaded_stats = mcp::cache_stats();
    ASSERT_GT(loaded_stats.estimated_memory_bytes, 1);

    mcp::set_memory_budget(loaded_stats.estimated_memory_bytes - 1);
    EXPECT_EQ(mcp::cache_stats().streams, 0);
}
